      }
      if (!dead) {
        for (var k = 0; k < G.peds.length; k += 1) {
          var ped = G.peds[k];
          if (ped.state !== 'down' && Math.hypot(ped.x - b.x, ped.y - b.y) < 14) {
            SB.knockPed(G, ped, false);
