            SB.spawnParticles(G, b.x, b.y, 8, '#9db8d6', 200);
            dead = true;
            break;
          }
        }
      }
    }
    if (!dead && !b.fromPlayer) {
      if (Math.hypot(p.x - b.x, p.y - b.y) < 15) {
        SB.damagePlayer(G, b.damage);
        dead = true;
      }
    }
    if (dead) {
      SB.spawnParticles(G, b.x, b.y, 4, '#ffffff', 120);
      G.bullets.splice(i, 1);
    }
  }
